-- Configurar parâmetros Dpote para todas as empresas com dpoteFilialNome configurado
UPDATE cashbarberConfig 
SET dpoteValorAssinaturas = 145000.00, dpotePorcentagemBarbearia = 65.00
WHERE dpoteFilialNome IS NOT NULL AND dpoteFilialNome != '';

-- Verificar resultado
SELECT empresaSlug, dpoteFilialNome, dpoteValorAssinaturas, dpotePorcentagemBarbearia FROM cashbarberConfig;

